import json, zipfile, os
from docx import Document
out = '/root/offer_letter_filled.docx'
data_path = '/root/employee_data.json'
with open(data_path, encoding='utf-8') as f:
    data = json.load(f)
if not os.path.exists(out):
    raise SystemExit('missing output file')
with zipfile.ZipFile(out) as z:
    unresolved = []
    for name in z.namelist():
        if name.endswith('.xml'):
            xml = z.read(name).decode('utf-8', errors='ignore')
            if '{{' in xml or '}}' in xml or 'IF_RELOCATION' in xml or 'END_IF_RELOCATION' in xml:
                unresolved.append(name)
    if unresolved:
        raise SystemExit('unresolved placeholders/markers in ' + ', '.join(unresolved))
def table_texts(table):
    for row in table.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                yield p.text
            for nested in cell.tables:
                yield from table_texts(nested)
doc = Document(out)
texts = []
texts.extend(p.text for p in doc.paragraphs)
for table in doc.tables:
    texts.extend(table_texts(table))
for section in doc.sections:
    texts.extend(p.text for p in section.header.paragraphs)
    for table in section.header.tables:
        texts.extend(table_texts(table))
    texts.extend(p.text for p in section.footer.paragraphs)
    for table in section.footer.tables:
        texts.extend(table_texts(table))
full = '\n'.join(texts)
required = [data['DOC_ID'], data['COMPANY_NAME'], data['CANDIDATE_FULL_NAME'], data['POSITION'], data['DEPARTMENT'], data['START_DATE'], data['MANAGER_NAME'], '$' + data['BASE_SALARY'] + ' per year', '$' + data['SIGNING_BONUS'], data['EQUITY_SHARES'] + ' shares', '$' + data['RELOCATION_AMOUNT'], data['RELOCATION_DAYS'] + ' days', data['PTO_DAYS'] + ' days of PTO', data['RESPONSE_DEADLINE'], data['HR_NAME'], data['HR_TITLE']]
missing = [s for s in required if s not in full]
if missing:
    raise SystemExit('missing expected snippets: ' + repr(missing))
print('OK')
